    let s = thaiToArabic(String(raw)).replace(CURRENCY_RE, '').trim();
    s = s.replace(/(?<=\d)\s*(?:\.-|-)(?=\s|$|\/)/g, '').trim();
    const neg = /^\(\s*(\d[\d,]*(?:\.\d+)?)\s*\)$/.exec(s);
    if (neg) return [dStr(dNeg(D(neg[1].replace(/,/g, '')))), null];
    const m = /^(-?\d[\d,]*(?:\.\d+)?)\s*(.*)$/.exec(s);
