    const dd = dec === null || dec === undefined ? 12 : dec;
    const num = a.v * (10n ** BigInt(b.s));
    const den = b.v * (10n ** BigInt(a.s));
    const neg = (num < 0n) !== (den < 0n);
    const n = (num < 0n ? -num : num) * (10n ** BigInt(dd));
