  function dStr(a) {                                 // python str(Decimal)
    if (a === null) return null;
    let t = (a.v < 0n ? '-' : '') + (a.v < 0n ? (-a.v) : a.v).toString();
    if (a.s === 0) return t;
    const neg = t[0] === '-'; if (neg) t = t.slice(1);
    while (t.length <= a.s) t = '0' + t;
    t = t.slice(0, t.length - a.s) + '.' + t.slice(t.length - a.s);
