      },
      uomGroup(u) {                                   // standard.py::uom_group
        if (u === null || u === undefined) return null;
        const x = String(u).trim().toUpperCase().replace(/ /g, '');
        const fx = foldTone(x);
        for (const [g, members] of Object.entries(this.uom_groups)) {
