    MAY: 5, 'พ.ค.': 5, 'พ.ค': 5, 'พฤษภาคม': 5,
    JUN: 6, JUNE: 6, 'มิ.ย.': 6, 'มิ.ย': 6, 'มิถุนายน': 6,
