  const PAGE_TYPE_MAP = {
    tax_invoice: 'TAX_INVOICE', invoice: 'INVOICE', po: 'PO', osp: 'OSP',
    delivery: 'DELIVERY_NOTE', delivery_note: 'DELIVERY_NOTE', supporting: 'SUPPORTING', other: 'UNKNOWN'
