  function buildExtraction(o) {
    const n5 = o.n05, n8 = o.n08, n10 = o.n10, cfg = o.cfg;
    const dpiE = Number(cfg.dpi_extract || 150);
    const W = Number(n8.img_w), H = Number(n8.img_h), invPage = Number(n5.invoice_page);
    const norm = (b) => {                                     // bbox_2d (0..1000 or 0..1) -> [x,y,w,h] 0..1
      if (!Array.isArray(b) || b.length !== 4) return null;
      const k = Math.max.apply(null, b.map(Number)) <= 1.0 ? 1.0 : 1000.0;
      let x0 = Number(b[0]) / k, y0 = Number(b[1]) / k, x1 = Number(b[2]) / k, y1 = Number(b[3]) / k;
      if (x1 < x0) { const t = x0; x0 = x1; x1 = t; }
      if (y1 < y0) { const t = y0; y0 = y1; y1 = t; }
      x0 = Math.max(0, Math.min(1, x0)); y0 = Math.max(0, Math.min(1, y0));
      x1 = Math.max(0, Math.min(1, x1)); y1 = Math.max(0, Math.min(1, y1));
      if (!(x1 > x0 && y1 > y0)) return null;
      return [x0, y0, x1 - x0, y1 - y0];
