      page_no: p.page_no,
      width_pt: p.page_no === invPage ? ptW : ptW,      // only the invoice page is measured (see metrics.note)
      height_pt: p.page_no === invPage ? ptH : ptH,
      rotation: Number(p.rotate_degrees || 0),
