    const r = await helpers.httpRequest({
      method: 'POST', url: PORT.oracleUrl, timeout: PORT.timeoutMs, returnFullResponse: true,
      headers: { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream',
